\begin{tikzpicture}[x=0.48cm,y=0.48cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{curveBlue}{HTML}{268CFF}
\path[use as bounding box] (-8.5,-3.7) rectangle (4.8,5.8);
\draw[black,line width=0.5pt,->] (-8,0)--(4,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-3)--(0,5) node[above] {$y$};
\draw[black,dashed,line width=0.4pt] (-4,-3)--(-4,5) node[above] {$x=-4$};
\draw[black,dashed,line width=0.4pt] (-8,1)--(4,1) node[right] {$y=1$};
\begin{scope}\clip (-8,-3) rectangle (4,5);
\draw[curveBlue,line width=0.8pt,samples=120,domain=-8:-4.25] plot (\x,{1-1/(\x+4)});
\draw[curveBlue,line width=0.8pt,samples=120,domain=-3.75:4] plot (\x,{1-1/(\x+4)});
\end{scope}
\fill[black] (-3,0) circle (1.3pt) (0,0.75) circle (1.3pt);
\node[below] at (-3,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$-3$\special{dvisvgm:raw </g>}};
\node[right] at (0,0.75) {\special{dvisvgm:raw <g data-graph-text="tick">}$\frac34$\special{dvisvgm:raw </g>}};
\end{tikzpicture}

